// Build today's LinkedIn task list. The cap is set by LinkedIn's own weekly invite
// limit, not by ambition: roughly 100 connection requests a week across an account,
// and accounts that push past it get restricted. 20 a day is the safe ceiling.
const CAP = Math.min(Number($env.LI_DAILY_CAP || 20), 25);
const MIN_FIT = Number($env.LI_MIN_FIT || 60);
const today = new Date().toISOString().slice(0, 10);

const STEPS = [
  { step: 0, action: 'view_profile', label: 'View profile', needs_copy: false, wait_days: 1 },
  { step: 1, action: 'connect', label: 'Connect with a note', needs_copy: true, wait_days: 4 },
  { step: 2, action: 'message', label: 'Message (if they accepted)', needs_copy: true, wait_days: 6 },
  { step: 3, action: 'engage', label: 'Comment on a recent post', needs_copy: false, wait_days: 0 }
];

const dropped = { no_linkedin: 0, low_fit: 0, suppressed: 0, not_due: 0, finished: 0, over_cap: 0 };
const due = [];

for (const item of $input.all()) {
  const lead = item.json;

  if (!lead.linkedin_url) { dropped.no_linkedin++; continue; }
  if (String(lead.stage || '') === 'suppressed') { dropped.suppressed++; continue; }
  if (Number(lead.fit_score || 0) < MIN_FIT) { dropped.low_fit++; continue; }

  const step = Number(lead.li_step || 0);
  if (step >= STEPS.length) { dropped.finished++; continue; }

  const nextDue = String(lead.li_next_due || '').slice(0, 10);
  if (nextDue && nextDue > today) { dropped.not_due++; continue; }

  due.push({ lead: lead, plan: STEPS[step] });
}

// Best fit first, so a capped day spends itself on the best people.
due.sort((a, b) => Number(b.lead.fit_score || 0) - Number(a.lead.fit_score || 0));

if (due.length > CAP) dropped.over_cap = due.length - CAP;
const batch = due.slice(0, CAP);

if (batch.length === 0) return [];

return batch.map((entry, index) => ({ json: Object.assign({}, entry.lead, {
  li_action: entry.plan.action,
  li_action_label: entry.plan.label,
  li_needs_copy: entry.plan.needs_copy,
  li_wait_days: entry.plan.wait_days,
  li_step_now: entry.plan.step,
  task_date: today,
  batch_size: batch.length,
  batch_dropped: dropped,
  batch_index: index
})}));

// Attach the copy, and enforce the 300-character connection-note limit here rather
// than trusting the model - LinkedIn silently truncates and the operator never notices.
const tasks = $('needs written copy?').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const task = Object.assign({}, tasks[i].json);
  const res = $input.all()[i].json || {};
  let copy = String(((((res.choices || [])[0]) || {}).message || {}).content || '').trim();

  if (task.li_action === 'connect' && copy.length > 300) {
    copy = copy.slice(0, 297).trim() + '...';
    task.copy_was_truncated = true;
  }

  task.li_copy = copy;
  out.push({ json: task });
}

return out;

// Steps that need no writing still need an instruction the operator can act on.
return $input.all().map((item) => ({ json: Object.assign({}, item.json, {
  li_copy: item.json.li_action === 'view_profile'
    ? 'Open the profile, spend ten seconds, close it. No action needed - this is the warm-up touch.'
    : 'Find their most recent post and leave one specific, non-generic comment.'
})}));

// One message the operator works top to bottom. Fifteen minutes, done by 09:15.
const tasks = $('merge tasks').all().map((i) => i.json);
if (!tasks.length) return [];

const dropped = tasks[0].batch_dropped || {};
const lines = [':busts_in_silhouette: *LinkedIn queue - ' + tasks[0].task_date + '* (' + tasks.length + ' touches, cap ' + ($env.LI_DAILY_CAP || 20) + ')', ''];

tasks.forEach((t, i) => {
  lines.push((i + 1) + '. *' + t.li_action_label + '* - ' + t.first_name + ' ' + t.last_name + ', ' + t.company);
  lines.push('   ' + t.linkedin_url);
  if (t.li_copy) lines.push('   > ' + String(t.li_copy).split('\n').join('\n   > '));
  if (t.copy_was_truncated) lines.push('   :scissors: _note was trimmed to 300 characters_');
  lines.push('');
});

lines.push('_Skipped: ' + (dropped.no_linkedin || 0) + ' no profile, ' + (dropped.low_fit || 0) + ' low fit, ' + (dropped.not_due || 0) + ' not due yet, ' + (dropped.over_cap || 0) + ' held by the cap._');
lines.push('_Mark done in the LinkedIn Tasks tab, or POST the lead_id to the /li-done webhook._');

return [{ json: { text: lines.join('\n') } }];

// Advance the sequence, or stop it. 'declined' and 'replied' both end the LinkedIn
// lane: one is a no, the other means a human has taken over.
const WAIT = { view_profile: 1, connect: 4, message: 6, engage: 0 };

return $input.all().map((item) => {
  const b = item.json.body || item.json;
  const outcome = String(b.outcome || 'done').toLowerCase();
  const step = Number(b.li_step || 0) + 1;

  const stop = outcome === 'declined' || outcome === 'replied';
  const waitDays = Number(b.wait_days || WAIT[b.action] || 3);
  const next = new Date(Date.now() + waitDays * 86400000).toISOString().slice(0, 10);

  return { json: {
    lead_id: b.lead_id,
    li_step: stop ? 99 : step,
    li_next_due: stop ? '' : next,
    li_last_outcome: outcome,
    updated_at: new Date().toISOString()
  }};
});
